'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const KEY='sangam-command-workspace-v1';
const TYPES={sector:'Sector',station:'Rail station',landmark:'Landmark',parking:'Parking summary',parking_area:'Parking footprint',crossing:'Crossing trace',water:'Water feature',approach:'Regional approach',locality:'Place / road',police:'Police (permanent)',custom:'Planning marker'};
const ICONS={sector:'▧',station:'▤',landmark:'◇',parking:'P',parking_area:'P',crossing:'⇄',water:'≈',approach:'↗',locality:'⌖',police:'▣',custom:'+'};
const STATUS={unknown:'Not assessed',normal:'Normal',monitor:'Monitor',restricted:'Restricted',closed:'Closed'};
const blank=()=>({schemaVersion:2,sectors:{},incidents:[],markers:[]});
let data,workspace=blank(),selected='sector-06',filter='all',mode='clean',visible=new Set(['sector','station','landmark','parking','water','crossing','approach','locality','custom','police','mela_road']),placing=false;
let mapEngine,lastSave=null,repositionId=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n).toLocaleString('en-IN');
const date=s=>s?new Date(s).toLocaleString('en-IN',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'No update';
const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`;
const allFeatures=()=>[...data.features,...workspace.markers];
const feature=id=>allFeatures().find(f=>f.id===id);
const pill=s=>`<span class="pill ${esc(s||'unknown')}">${esc(STATUS[s]||STATUS.unknown)}</span>`;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(workspace));lastSave=new Date().toISOString();$('#saved-state').textContent=`Saved in this browser · ${date(lastSave)}`;renderCounts();return true}catch{toast('Browser storage is unavailable or full. Export your workspace to keep changes.');return false}}
function setView(name){$$('.view').forEach(e=>e.classList.toggle('active',e.id===`${name}-view`));$$('.nav').forEach(e=>e.classList.toggle('active',e.dataset.view===name));if(name==='operations')renderOperations();if(name==='atlas')requestAnimationFrame(()=>mapEngine?.map.invalidateSize())}
async function setMode(next){if(await mapEngine.setMode(next)){mode=next;$$('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));renderMap()}}
function renderCounts(){const n=Object.keys(workspace.sectors).length;$('#ops-count').innerHTML=`${String(n).padStart(2,'0')}<small>sectors with manual updates</small>`;$('#feature-count').textContent=allFeatures().length}
function renderDirectory(){const q=$('#search').value.toLowerCase().trim();const items=allFeatures().filter(f=>!$('#low-confidence')?.checked||f.confidence==='low').filter(f=>(filter==='all'||(filter==='other'?!['sector','station','landmark','parking','parking_area','crossing'].includes(f.type):(f.type===filter||(filter==='parking'&&f.type==='parking_area'))))&&`${f.name} ${f.zone||''} ${f.id}`.toLowerCase().includes(q));$('#results-count').textContent=items.length+' items';$('#directory').innerHTML=items.length?items.map(f=>`<button class="feature-row ${f.id===selected?'selected':''}" data-select="${esc(f.id)}"><span class="feature-icon">${f.number||ICONS[f.type]}</span><span><strong>${esc(f.name)}</strong><small>${esc(f.zone||TYPES[f.type])}${!f.geometry?' · unlocated':f.confidence==='low'?' · low confidence':''}</small></span><span class="arrow">›</span></button>`).join(''):'<div class="empty">No matching feature.<br>Try a sector number or station name.</div>'}
function select(id,focus=false){if(!feature(id))return;selected=id;renderDirectory();renderDetail();renderMap();mapEngine?.clearRoute();if(focus)focusFeature(feature(id));if(feature(id).type==='station')mapEngine?.showRoute(id)}
function focusFeature(f){mapEngine.focus(f)}
function renderMap(){mapEngine?.render(allFeatures(),visible,selected,workspace.sectors)}
function renderDetail(){const f=feature(selected);if(!f)return;const op=workspace.sectors[f.id]||{};const type=TYPES[f.type];let confidence=f.type==='custom'?(f.geometry?'User-added geographic location':'Legacy marker · placement needed'):`${f.confidence} confidence${!f.geometry?' · location unresolved':''}`;let html=`<div class="detail-top"><div class="detail-eyebrow">${esc(type.toUpperCase())} DETAILS</div><div class="detail-heading"><span class="detail-number">${f.number||ICONS[f.type]}</span><div><h2>${esc(f.name)}</h2><p>${esc(f.zone||f.kind||type)}</p></div></div><span class="tag ${f.confidence==='low'?'review':''}">${confidence}</span></div><div class="detail-body">`;
if(f.type==='sector'){const count=op.count,cap=op.capacity,ratio=count!=null&&cap>0?count/cap:null;html+=`<div class="status-bar"><h3 style="margin:0">Operational snapshot</h3>${pill(op.status)}</div><div class="occupancy-box"><div class="occupancy-value">${count!=null?fmt(count):'—'}<small>people recorded</small></div><div class="progress"><span style="width:${ratio===null?0:Math.min(100,ratio*100)}%;${ratio>1?'background:#b35348':''}"></span></div><p>${cap!=null?'Recorded capacity '+fmt(cap):'Capacity not set'}${ratio!==null?` · ${Math.round(ratio*100)}%`:''}</p></div>${ratio>1?'<p class="inline-note">Recorded count exceeds the capacity entered for this sector.</p>':''}<form id="sector-form"><div class="form-grid"><div class="field"><label for="count">People count</label><input id="count" name="count" type="number" min="0" max="100000000" step="1" placeholder="Unknown" value="${count??''}"></div><div class="field"><label for="capacity">Capacity</label><input id="capacity" name="capacity" type="number" min="1" max="100000000" step="1" placeholder="Not set" value="${cap??''}"></div></div><div class="field"><label for="sector-status">Operational status</label><select id="sector-status" name="status">${Object.entries(STATUS).map(([v,t])=>`<option value="${v}" ${op.status===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="team">Assigned team</label><input id="team" name="team" maxlength="100" placeholder="Team name / call sign" value="${esc(op.team||'')}"></div><div class="field"><label for="notes">Field notes</label><textarea id="notes" name="notes" maxlength="2000" placeholder="Access conditions, observations…">${esc(op.notes||'')}</textarea></div><button class="button primary full" type="submit">Save sector update ↗</button><p class="subtle">${op.updatedAt?'Last saved '+date(op.updatedAt):'No operational update yet.'}<br>Capacity and status are entered by your team.</p></form><div class="detail-section"><h3>Sector activity</h3><p>${workspace.incidents.filter(i=>i.featureId===f.id&&i.status==='open').length} open incidents recorded</p><button class="button full" data-incident="${f.id}">＋ Record incident here</button></div>`}
else{html+=`<h3>About this feature</h3><p>${esc(f.description)}</p>`;if(f.type==='parking')html+=`<div class="detail-facts"><span>Existing lots</span><strong>${f.currentLots}</strong><span>Existing area</span><strong>${f.currentHectares} ha</strong><span>New lots earmarked</span><strong>${f.newLots}</strong><span>New area</span><strong>${f.newHectares} ha</strong></div><p class="inline-note">2025 source summary. This marker indicates a region, not an individual parking entrance.</p>`;if(f.type==='parking_area')html+=`<p class="inline-note">${f.geometry?'OSM parking location; access and current availability need field confirmation.':'Legacy parking reference has no verified geographic match.'}</p>`;if(f.type==='crossing')html+='<p class="inline-note">Tracing reference, not an official bridge number. Unlocated references are not included as network edges.</p>';if(f.type==='custom')html+=`<div class="detail-section"><button class="button full" data-edit-marker="${esc(f.id)}">Edit planning marker</button><button class="button full" data-reposition-marker="${esc(f.id)}">Place / move on map</button><button class="button full danger" data-delete-marker="${esc(f.id)}">Remove marker</button></div>`;html+=`<div class="detail-section"><button class="button full" data-incident="${esc(f.id)}">＋ Record incident here</button></div>`}
if(f.type==='crossing'){const connection=mapEngine?.validation?.pontoon_connectivity?.find(p=>p.id===f.id);if(connection)html+=`<p class="inline-note">Walking graph: ${connection.attached_endpoints} of 2 approaches attached.${connection.both_ends_connected_to_road?'':' This candidate is not a verified through-route.'}</p>`}
if(f.type==='station'){const route=mapEngine?.routeFor(f.id);const metres=route?.properties?.length_m||route?.properties?.distance_m;html+=`<div class="detail-section"><h3>Walking route to Sangam</h3><p>${metres?`${(metres/1000).toFixed(2)} km · research graph`:'Route data loading or unavailable'}</p><button class="button full" id="show-route" ${route?'':'disabled'}>Show walking route ↗</button><p class="subtle">Access links and temporary routes require field verification.</p></div>`}
html+=`<div class="detail-section"><h3>Source & location</h3><p>${esc(f.source||'User-added')}<br>${f.coordinates?`${f.coordinates[1].toFixed(6)}° N, ${f.coordinates[0].toFixed(6)}° E`:'No independently verified coordinate'}${f.area_ha!=null?`<br>${Number(f.area_ha).toFixed(2)} hectares`:''}</p>${f.method?`<p class="subtle">${esc(f.method)}</p>`:''}<button class="button full" id="inspect-source">Inspect satellite reference ↗</button></div></div>`;$('#detail').innerHTML=html;
$('#sector-form')?.addEventListener('submit',e=>{e.preventDefault();const form=new FormData(e.target);workspace.sectors[f.id]={count:form.get('count')===''?null:Number(form.get('count')),capacity:form.get('capacity')===''?null:Number(form.get('capacity')),status:form.get('status'),team:form.get('team').trim(),notes:form.get('notes').trim(),updatedAt:new Date().toISOString()};const ok=save();renderDetail();renderMap();if(ok)toast(`${f.name} update saved in this browser`)});$('#inspect-source').onclick=()=>{setMode('overlay');if(f.geometry)focusFeature(f)};$('#show-route')?.addEventListener('click',()=>mapEngine.showRoute(f.id))}

function renderOperations(){let ops=Object.values(workspace.sectors),known=ops.filter(o=>o.count!==null),total=known.reduce((s,o)=>s+o.count,0),open=workspace.incidents.filter(i=>i.status==='open').length;$('#operations-summary').innerHTML=[['People recorded',known.length?fmt(total):'—'],['Sectors reporting',`${known.length} / 25`],['Open incidents',open],['Planning markers',workspace.markers.length]].map(([t,v])=>`<div class="summary-card"><span>${t}</span><strong>${v}</strong></div>`).join('');$('#operations-table').innerHTML=data.features.filter(f=>f.type==='sector').map(f=>{const o=workspace.sectors[f.id]||{};return `<tr><td><strong>${f.name}</strong></td><td>${f.zone}</td><td>${o.count!=null?fmt(o.count):'—'} / ${o.capacity!=null?fmt(o.capacity):'—'}</td><td>${pill(o.status)}</td><td>${esc(o.team||'Unassigned')}</td><td>${date(o.updatedAt)}</td><td><button class="button" data-open-sector="${f.id}">Open ↗</button></td></tr>`}).join('');$('#incident-list').innerHTML=workspace.incidents.length?[...workspace.incidents].reverse().map(i=>`<article class="incident ${i.status==='resolved'?'resolved':''}"><div><h3>${esc(i.title)} <span class="pill ${i.severity==='high'?'restricted':'monitor'}">${esc(i.severity)}</span> ${i.status==='resolved'?'<span class="pill normal">Resolved</span>':''}</h3><p>${esc(feature(i.featureId)?.name||'General area')} · ${esc(i.description)}</p><small>Recorded ${date(i.createdAt)}${i.resolvedAt?' · resolved '+date(i.resolvedAt):''}</small></div><button class="button" data-resolve="${esc(i.id)}">${i.status==='resolved'?'Reopen':'Resolve'}</button></article>`).join(''):'<div class="empty">No incidents recorded.<br>Add a report from a sector or any map feature.</div>'}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal();$('#modal-content').querySelector('input,select')?.focus()}
function incidentDialog(id=selected){modal(`<h2>Record an incident</h2><p>A local planning record with a source feature attached.</p><form id="incident-form"><div class="field"><label for="incident-feature">Location</label><select id="incident-feature" name="featureId">${allFeatures().map(f=>`<option value="${esc(f.id)}" ${f.id===id?'selected':''}>${esc(f.name)}</option>`).join('')}</select></div><div class="field"><label for="incident-title">Title</label><input id="incident-title" name="title" required maxlength="150" placeholder="What is happening?"></div><div class="field"><label for="incident-severity">Priority</label><select id="incident-severity" name="severity"><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option></select></div><div class="field"><label for="incident-description">Details</label><textarea id="incident-description" name="description" required maxlength="2000" placeholder="Observations and action needed"></textarea></div><div class="modal-actions"><button type="button" class="button" data-close>Cancel</button><button class="button primary">Save incident</button></div></form>`);$('#incident-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);workspace.incidents.push({id:uid(),featureId:f.get('featureId'),title:f.get('title').trim(),description:f.get('description').trim(),severity:f.get('severity'),status:'open',createdAt:new Date().toISOString()});const ok=save();$('#modal').close();renderDetail();renderOperations();if(ok)toast('Incident saved in this browser')}}
function markerDialog(point,existing){modal(`<h2>${existing?'Edit':'Add'} planning marker</h2><p>Place your own operational facilities on the map. This is a user addition, separate from source data.</p><form id="marker-form"><div class="field"><label for="marker-name">Name</label><input id="marker-name" name="name" maxlength="100" required placeholder="e.g. North medical post" value="${esc(existing?.name||'')}"></div><div class="field"><label for="marker-kind">Type</label><select name="kind" id="marker-kind">${['Gate','Medical point','Control post','Assembly point','Barrier','Parking','Other'].map(k=>`<option ${existing?.kind===k?'selected':''}>${k}</option>`).join('')}</select></div><div class="field"><label for="marker-description">Notes</label><textarea id="marker-description" name="description" maxlength="2000" placeholder="Planned purpose, team, access notes">${esc(existing?.description||'')}</textarea></div><div class="modal-actions"><button type="button" class="button" data-close>Cancel</button><button class="button primary">Save marker</button></div></form>`);$('#marker-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const record={id:existing?.id||`custom-${uid()}`,name:f.get('name').trim(),type:'custom',kind:f.get('kind'),description:f.get('description').trim(),coordinates:point?.coordinates||existing?.coordinates||null,geometry:(point?.coordinates||existing?.coordinates)?{type:'Point',coordinates:point?.coordinates||existing.coordinates}:null,confidence:'low',source:'user',location_status:(point?.coordinates||existing?.coordinates)?'placed':'unresolved',...(existing?.legacy_location?{legacy_location:existing.legacy_location}:{}),updatedAt:new Date().toISOString()};if(existing)workspace.markers=workspace.markers.map(m=>m.id===existing.id?record:m);else workspace.markers.push(record);const ok=save();$('#modal').close();renderDirectory();select(record.id);if(ok)toast('Planning marker saved')}}
function download(name,obj){const url=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function validateWorkspace(input){
if(!input||typeof input!=='object'||![1,2].includes(input.schemaVersion))throw Error('Unsupported workspace format');
const state=input.workspace||input;if(!state.sectors||typeof state.sectors!=='object'||Array.isArray(state.sectors)||!Array.isArray(state.incidents)||!Array.isArray(state.markers))throw Error('Missing workspace records');
if(state.markers.length>1000||state.incidents.length>10000)throw Error('Too many records');const out=blank();const str=(v,max)=>typeof v==='string'&&v.length<=max;const time=v=>typeof v==='string'&&Number.isFinite(Date.parse(v));
for(const[id,o]of Object.entries(state.sectors)){if(!data.features.some(f=>f.id===id&&f.type==='sector')||!o||!Object.hasOwn(STATUS,o.status)||!str(o.team,100)||!str(o.notes,2000)||!time(o.updatedAt))throw Error('Invalid sector record');for(const key of['count','capacity'])if(o[key]!==null&&(!Number.isInteger(o[key])||o[key]<(key==='capacity'?1:0)||o[key]>100000000))throw Error('Invalid crowd count or capacity');out.sectors[id]={count:o.count,capacity:o.capacity,status:o.status,team:o.team,notes:o.notes,updatedAt:o.updatedAt}}
const ids=new Set(data.features.map(f=>f.id));for(const m of state.markers){if(!m||!str(m.id,150)||!m.id.startsWith('custom-')||ids.has(m.id)||!str(m.name,100)||!m.name.trim()||m.type!=='custom'||!str(m.kind,80)||!str(m.description,2000))throw Error('Invalid planning marker');let coordinates=m.coordinates??null,legacy=m.legacy_location;
if(Array.isArray(m.xy)){if(m.xy.length!==2||m.xy.some(n=>!Number.isFinite(n)||n<0)||m.xy[0]>1284||m.xy[1]>2000)throw Error('Invalid legacy marker');legacy={coordinateSystem:'unregistered-image',xy:m.xy};coordinates=null}
if(coordinates!==null&&(!Array.isArray(coordinates)||coordinates.length!==2||!coordinates.every(Number.isFinite)||coordinates[0]<81.7||coordinates[0]>82.1||coordinates[1]<25.25||coordinates[1]>25.65))throw Error('Marker outside the research area');
ids.add(m.id);out.markers.push({id:m.id,name:m.name,type:'custom',kind:m.kind,description:m.description,coordinates,geometry:coordinates?{type:'Point',coordinates}:null,source:'user',confidence:'low',location_status:coordinates?'placed':'unresolved',...(legacy?{legacy_location:legacy}:{}),updatedAt:time(m.updatedAt)?m.updatedAt:new Date().toISOString()})}
const incidentIds=new Set();for(const i of state.incidents){if(!i||!str(i.id,150)||incidentIds.has(i.id)||!ids.has(i.featureId)||!str(i.title,150)||!i.title.trim()||!str(i.description,2000)||!['low','medium','high'].includes(i.severity)||!['open','resolved'].includes(i.status)||!time(i.createdAt))throw Error('Invalid incident record');incidentIds.add(i.id);out.incidents.push({id:i.id,featureId:i.featureId,title:i.title,description:i.description,severity:i.severity,status:i.status,createdAt:i.createdAt,...(time(i.resolvedAt)?{resolvedAt:i.resolvedAt}:{})})}return out}

function setupEvents(){$$('.nav').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#search').oninput=renderDirectory;$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(e=>e.classList.toggle('active',e===b));renderDirectory()});$$('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));$('#zoom-in').onclick=()=>mapEngine.map.zoomIn();$('#zoom-out').onclick=()=>mapEngine.map.zoomOut();$('#fit').onclick=()=>mapEngine.fit();$('#add-marker').onclick=()=>{placing=!placing;mapEngine.placementMode(placing);$('#add-marker').classList.toggle('placing',placing);$('#add-marker').textContent=placing?'Cancel placement':'＋ Place marker';$('#map-hint').textContent=placing?'Click a location inside the map to add your marker':'Drag to explore · Scroll to zoom · Click a feature'};
$('#export').onclick=()=>{download('sangam-workspace.json',{schemaVersion:2,exportedAt:new Date().toISOString(),map:data,workspace});toast('Workspace exported as JSON')};$('#download-data').onclick=()=>download('sangam-map-data.json',data);$('#new-incident').onclick=()=>incidentDialog();$('#import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10000000)throw Error('File is too large');const imported=validateWorkspace(JSON.parse(await file.text()));modal(`<h2>Import workspace?</h2><p>This replaces the local operational records with ${Object.keys(imported.sectors).length} sector updates, ${imported.incidents.length} incidents and ${imported.markers.length} markers. Export your current workspace first if you want to keep a copy.</p><div class="modal-actions"><button class="button" data-close>Cancel</button><button class="button primary" id="confirm-import">Replace local records</button></div>`);$('#confirm-import').onclick=()=>{workspace=imported;selected='sector-06';const ok=save();$('#modal').close();renderDirectory();renderDetail();renderMap();renderOperations();if(ok)toast('Workspace imported')};}catch(err){toast('Import failed: '+err.message)}e.target.value=''};
document.addEventListener('click',e=>{let b=e.target.closest('[data-select]');if(b)select(b.dataset.select,true);b=e.target.closest('[data-open-sector]');if(b){setView('atlas');select(b.dataset.openSector,true)}b=e.target.closest('[data-incident]');if(b)incidentDialog(b.dataset.incident);if(e.target.closest('[data-close]'))$('#modal').close();b=e.target.closest('[data-resolve]');if(b){const i=workspace.incidents.find(i=>i.id===b.dataset.resolve);i.status=i.status==='open'?'resolved':'open';if(i.status==='resolved')i.resolvedAt=new Date().toISOString();else delete i.resolvedAt;save();renderOperations();renderDetail()}b=e.target.closest('[data-edit-marker]');if(b)markerDialog(null,feature(b.dataset.editMarker));b=e.target.closest('[data-delete-marker]');if(b){const id=b.dataset.deleteMarker;if(workspace.incidents.some(i=>i.featureId===id)){toast('This marker has incident records attached; edit it instead.');return}modal('<h2>Remove planning marker?</h2><p>This removes the marker from your local workspace.</p><div class="modal-actions"><button class="button" data-close>Cancel</button><button class="button primary" id="confirm-delete">Remove marker</button></div>');$('#confirm-delete').onclick=()=>{workspace.markers=workspace.markers.filter(m=>m.id!==id);save();$('#modal').close();select('sector-06')}}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();setView('atlas');$('#search').focus()}if(e.key==='Escape'&&placing)$('#add-marker').click()});$('#low-confidence').onchange=e=>{mapEngine.setLowOnly(e.target.checked);renderDirectory()};document.addEventListener('click',e=>{const b=e.target.closest('[data-reposition-marker]');if(b){repositionId=b.dataset.repositionMarker;if(!placing)$('#add-marker').click();toast('Click the actual location to reposition this marker.')}})}

async function init(){try{await window.leafletReady;const r=await fetch('map-data.json',{cache:'no-cache'});if(!r.ok)throw Error('Map data could not load');data=await r.json();try{const local=localStorage.getItem(KEY);if(local){workspace=validateWorkspace(JSON.parse(local));if(JSON.parse(local).schemaVersion===1){if(!localStorage.getItem(KEY+'-backup-before-geographic-v2'))localStorage.setItem(KEY+'-backup-before-geographic-v2',local);localStorage.setItem(KEY,JSON.stringify(workspace))}}}catch{toast('Saved workspace could not be read; the original stored data has not been overwritten.')}
mapEngine=new SangamMap({onSelect:id=>select(id),onReady:()=>{if(feature(selected))renderDetail();updateSourceInventory()},onPlace:point=>{if(point.coordinates[0]<81.7||point.coordinates[0]>82.1||point.coordinates[1]<25.25||point.coordinates[1]>25.65){toast('Place the marker inside the Prayagraj research area.');return}$('#add-marker').click();const existing=repositionId?feature(repositionId):null;repositionId=null;markerDialog(point,existing)}});await mapEngine.init(data);
$('#layers').innerHTML=[['sector','Sectors'],['station','Rail stations'],['landmark','Temples'],['crossing','Pontoons'],['parking','Parking'],['water','Rivers'],['police','Police · permanent'],['police_temporary','Police · mela'],['road','OSM roads'],['mela_road','Mela roads'],['railway','Railway lines'],['network','Walking network'],['routes','Station routes'],['approach','Approaches'],['locality','Place labels'],['custom','Your markers']].map(([v,t])=>`<label class="layer-toggle"><input type="checkbox" value="${v}" ${visible.has(v)?'checked':''}>${t}</label>`).join('');$$('#layers input').forEach(i=>i.onchange=()=>{if(i.checked)visible.add(i.value);else visible.delete(i.value);renderMap()});renderCounts();renderDirectory();renderDetail();renderMap();setupEvents();updateSourceInventory();}catch(e){$('#detail').innerHTML=`<div class="detail-body"><h2>Map could not load</h2><p>${esc(e.message)}</p><p>Serve this folder over HTTP, then reload.</p></div>`}}
function updateSourceInventory(){const mapped=data.features.filter(f=>f.geometry).length;$('#coverage-count').textContent=`${mapped} geographically located features; ${data.features.length-mapped} unresolved references retain their IDs.`;$('#source-area').textContent=data.features.filter(f=>f.type==='sector').reduce((a,f)=>a+(f.area_ha||0),0).toFixed(1)+' ha';const v=mapEngine?.validation;if(v)$('#network-summary').textContent=`Connected export: ${fmt(v.canonical_export.nodes)} nodes / ${fmt(v.canonical_export.edges)} edges. All 9 stations, 25 sector points and 36 mapped parking points reach Sangam. ${v.pontoon_connectivity.filter(p=>p.both_ends_connected_to_road).length} of 27 observed pontoon candidates have both approaches attached.`;}

init();
